choose.when:
select t.id, t.name, (t.c1 + t.c2 + t.c3 + t.c4) as refCount,
       concat_ws('、',
           if(t.c1 > 0, concat(t.c1, ' 只猫咪'), null),
           if(t.c2 > 0, concat(t.c2, ' 间病房'), null),
           if(t.c3 > 0, concat(t.c3, ' 条诊断'), null),
           if(t.c4 > 0, concat(t.c4, ' 条费用'), null)) as detail
  from (
    select b.base_id as id, b.base_name as name,
           (select count(1) from cat_profile p where p.base_id = b.base_id and p.del_flag = '0') c1,
           (select count(1) from cat_ward w where w.base_id = b.base_id and w.del_flag = '0') c2,
           (select count(1) from cat_diagnosis d where d.base_id = b.base_id and d.del_flag = '0') c3,
           (select count(1) from cat_expense e where e.base_id = b.base_id and e.del_flag = '0') c4
      from cat_base b
     where b.base_id in
    #{id}
  ) t

select t.id, t.name, (t.c1 + t.c2 + t.c3 + t.c4 + t.c5 + t.c6) as refCount,
       concat_ws('、',
           if(t.c1 > 0, concat(t.c1, ' 条出入库'), null),
           if(t.c2 > 0, concat(t.c2, ' 条用药'), null),
           if(t.c3 > 0, concat(t.c3, ' 条疫苗'), null),
           if(t.c4 > 0, concat(t.c4, ' 条驱虫'), null),
           if(t.c5 > 0, concat(t.c5, ' 条诊断明细'), null),
           if(t.c6 > 0, concat(t.c6, ' 个检查项目'), null)) as detail
  from (
    select m.material_id as id, m.material_name as name,
           (select count(1) from cat_stock_record r where r.material_id = m.material_id) c1,
           (select count(1) from cat_medication d where d.material_id = m.material_id and d.del_flag = '0') c2,
           (select count(1) from cat_vaccine v where v.material_id = m.material_id and v.del_flag = '0') c3,
           (select count(1) from cat_deworm w where w.material_id = m.material_id and w.del_flag = '0') c4,
           (select count(1) from cat_diagnosis_item i where i.material_id = m.material_id) c5,
           (select count(1) from cat_check_item ci where ci.material_id = m.material_id and ci.del_flag = '0') c6
      from cat_material m
     where m.material_id in
    #{id}
  ) t

select t.id, t.name, (t.c1 + t.c2 + t.c3) as refCount,
       concat_ws('、',
           if(t.c1 > 0, concat(t.c1, ' 个子项目'), null),
           if(t.c2 > 0, concat(t.c2, ' 条诊断明细'), null),
           if(t.c3 > 0, concat(t.c3, ' 条处方明细'), null)) as detail
  from (
    select ci.item_id as id, ci.item_name as name,
           (select count(1) from cat_check_item s where s.parent_id = ci.item_id and s.del_flag = '0') c1,
           (select count(1) from cat_diagnosis_item di where di.item_id = ci.item_id) c2,
           (select count(1) from cat_prescription_item pi where pi.item_id = ci.item_id) c3
      from cat_check_item ci
     where ci.item_id in
    #{id}
  ) t

select p.cat_id as id, concat(p.cat_name, '（', p.archive_no, '）') as name,
       (ifnull(a.c1,0) + ifnull(b.c1,0) + ifnull(c.c1,0) + ifnull(d.c1,0)
        + ifnull(e.c1,0) + ifnull(f.c1,0) + ifnull(g.c1,0)) as refCount,
       concat_ws('、',
           if(ifnull(a.c1,0) > 0, concat(ifnull(a.c1,0), ' 条病历'), null),
           if(ifnull(b.c1,0) > 0, concat(ifnull(b.c1,0), ' 条用药'), null),
           if(ifnull(c.c1,0) > 0, concat(ifnull(c.c1,0), ' 条疫苗'), null),
           if(ifnull(d.c1,0) > 0, concat(ifnull(d.c1,0), ' 条驱虫'), null),
           if(ifnull(e.c1,0) > 0, concat(ifnull(e.c1,0), ' 张照片'), null),
           if(ifnull(f.c1,0) > 0, concat(ifnull(f.c1,0), ' 条费用'), null),
           if(ifnull(g.c1,0) > 0, concat(ifnull(g.c1,0), ' 条其它记录'), null)) as detail
  from cat_profile p
  left join (select cat_id, count(1) c1 from cat_diagnosis where del_flag = '0' group by cat_id) a on a.cat_id = p.cat_id
  left join (select cat_id, count(1) c1 from cat_medication where del_flag = '0' group by cat_id) b on b.cat_id = p.cat_id
  left join (select cat_id, count(1) c1 from cat_vaccine where del_flag = '0' group by cat_id) c on c.cat_id = p.cat_id
  left join (select cat_id, count(1) c1 from cat_deworm where del_flag = '0' group by cat_id) d on d.cat_id = p.cat_id
  left join (select cat_id, count(1) c1 from cat_photo group by cat_id) e on e.cat_id = p.cat_id
  left join (select cat_id, count(1) c1 from cat_expense where del_flag = '0' group by cat_id) f on f.cat_id = p.cat_id
  left join (select cat_id, count(1) c1 from cat_flow group by cat_id) g on g.cat_id = p.cat_id
 where p.cat_id in
#{id}
